fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    // Clear the output vector to ensure it's empty before filling
    avgs.clear();
    
    // Iterate over all indices simultaneously
    for i in 0..vals_1.len() {
        let val1 = vals_1[i];
        let val2 = vals_2[i];
        let cond1 = conds_1[i];
        let cond2 = conds_2[i];
        
        // Calculate the average based on the conditions
        let avg = match (cond1, cond2) {
            (true, true) => (val1 + val2) / 2,
            (true, false) => val1,
            (false, true) => val2,
            // The problem states at least one boolean is true per index,
            // so (false, false) should never occur
            (false, false) => unreachable!("At least one boolean must be true per index"),
        };
        
        avgs.push(avg);
    }
}